CREATE OR REPLACE FUNCTION calculate_size_compatibility(p_donor_id text, p_recipient_id text)
RETURNS numeric AS $$
DECLARE
    donor_bmi numeric;
    recip_bmi numeric;
BEGIN
    -- Get donor BMI from demographics.physicalstats JSON
    SELECT INTO donor_bmi (d.physicalstats->>'Bmi_Value')::numeric
    FROM demographics d
    WHERE d.contrib_registry = p_donor_id;

    -- Get recipient BMI from recipients_demographics
    SELECT INTO recip_bmi r.bmi_val
    FROM recipients_demographics r
    WHERE r.recip_registry = p_recipient_id;

    -- Handle missing BMI values
    IF donor_bmi IS NULL OR recip_bmi IS NULL OR recip_bmi = 0 THEN
        RETURN NULL;
    END IF;

    -- Calculate size compatibility score: S_size = 1 - |BMI_donor / BMI_recipient - 1|
    RETURN ROUND(CAST(1 - ABS(donor_bmi / recip_bmi - 1) AS numeric), 4);
END;
$$ LANGUAGE plpgsql;

